-- Rodos Siena: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-59qgkd','rodos-official-13h8iec','rodos-official-13wj8rf')) <> 3 then raise exception 'Не знайдено всі моделі Rodos Siena для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-59qgkd';
delete from public.product_variants where product_slug = 'rodos-official-59qgkd';
delete from public.product_media where product_slug = 'rodos-official-59qgkd' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-13h8iec';
delete from public.product_variants where product_slug = 'rodos-official-13h8iec';
delete from public.product_media where product_slug = 'rodos-official-13h8iec' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-13wj8rf';
delete from public.product_variants where product_slug = 'rodos-official-13wj8rf';
delete from public.product_media where product_slug = 'rodos-official-13wj8rf' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-59qgkd','rodos-official-13h8iec','rodos-official-13wj8rf') group by product_slug order by product_slug;